text:
{
  "title": "地方税法等の改正",
  "lead": {
    "es": "令和《れいわ》6年度《ねんど》の住民税《じゅうみんぜい》を決《き》まった額《がく》だけ減《へ》らすことや、法人事業税《ほうじんじぎょうぜい》の見直《みなお》しなどを決《き》めた法律《ほうりつ》。",
    "hs": "令和6年度分の個人住民税の定額｜減税《げんぜい》や、法人事業税の「外形標準｜課税《かぜい》」の対象となる法人の見直しなどを定めた、地方税法などを改正する法律。",
    "std": "令和6年度分の個人住民税の定額減税や、法人事業税の外形標準課税の対象法人の見直しなどを定めた、地方税法などの改正法。",
    "univ": "令和6年度分の個人住民税の定額減税、法人事業税の外形標準課税の適用対象法人の見直し等を内容とする、地方税法等の一部を改正する法律。"
  },
  "facts": [
    {
      "es": "令和《れいわ》6年度《ねんど》の個人住民税《こじんじゅうみんぜい》を、決《き》まった額《がく》だけ減《へ》らす。※正確《せいかく》には「定額減税《ていがくげんぜい》を実施《じっし》する」。",
      "hs": "令和6年度分の個人住民税について、定額｜減税《げんぜい》（決まった額だけ税を減らすこと）を行う。",
      "std": "令和6年度分の個人住民税について、定額減税を実施する。",
      "univ": "令和6年度分の個人住民税について、定額減税を実施する。"
    },
    {
      "es": "会社《かいしゃ》などにかかる法人事業税《ほうじんじぎょうぜい》で、外形標準課税《がいけいひょうじゅんかぜい》というかけ方《かた》の対象《たいしょう》になる会社《かいしゃ》を見直《みなお》す。資本金《しほんきん》を減《へ》らすことなどで、対象《たいしょう》の会社《かいしゃ》がへっていることなどに対応《たいおう》するため。※正確《せいかく》には「減資等《げんしとう》により」。",
      "hs": "法人事業税で、「外形標準｜課税《かぜい》」の対象となる法人を見直す。減資《げんし》（資本金を減らすこと）などによって、対象の法人が減っていることなどの課題に対応するためである。",
      "std": "法人事業税について、減資などにより外形標準課税の対象法人が減っていることなどの課題に対応するため、その適用対象法人を見直す。",
      "univ": "法人事業税について、減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、その適用対象法人の見直しを行う。"
    },
    {
      "es": "固定資産税《こていしさんぜい》と都市計画税《としけいかくぜい》についてのきまり。令和《れいわ》6年度《ねんど》に土地《とち》などの値打《ねう》ちを見直《みなお》すとき、今《いま》の土地《とち》の負担《ふたん》を調整《ちょうせい》するしくみなどを続《つづ》ける。※正確《せいかく》には「評価替《ひょうかが》え」に当《あ》たり「負担調整措置等《ふたんちょうせいそちとう》を継続《けいぞく》する」。",
      "hs": "固定資産税と都市計画税について、令和6年度の評価｜替《が》え（土地などの値打ちを見直すこと）に当たり、今の土地の負担《ふたん》調整｜措置《そち》などを続ける。",
      "std": "固定資産税と都市計画税について、令和6年度の評価替えに当たり、現行の土地に関する負担調整措置などを継続する。",
      "univ": "固定資産税及び都市計画税について、令和6年度の評価替えに当たり、現行の土地に係る負担調整措置等を継続する。"
    },
    {
      "es": "森林環境譲与税《しんりんかんきょうじょうよぜい》を分《わ》けるときの基準《きじゅん》を見直《みなお》す。",
      "hs": "森林｜環境《かんきょう》｜譲与税《じょうよぜい》について、譲与《じょうよ》の基準を見直す。",
      "std": "森林環境譲与税について、譲与基準を見直す。",
      "univ": "森林環境譲与税について、譲与基準の見直しを行う。"
    },
    {
      "es": "税《ぜい》を軽《かる》くするしくみなどを、整理《せいり》したり見直《みなお》したりする。※正確《せいかく》には「税負担軽減措置等《ぜいふたんけいげんそちとう》の整理合理化等《せいりごうりかとう》を行《おこな》う」。",
      "hs": "税の負担《ふたん》を軽くする措置《そち》などの整理・合理化などを行う。",
      "std": "税負担軽減措置などの整理合理化などを行う。",
      "univ": "税負担軽減措置等の整理合理化等を行う。"
    },
    {
      "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、令和《れいわ》6年《ねん》4月《がつ》1日《ついたち》から使《つか》われ始《はじ》める。",
      "hs": "この法律は、一部を除き、令和6年4月1日から施行《しこう》する（使われ始める）。",
      "std": "この法律は、一部を除き、令和6年4月1日から施行する。",
      "univ": "この法律は、一部を除き、令和6年4月1日から施行する。"
    }
  ]
}
